# Translated from the gallery's helical model. Do not edit.
def loft_tooth(in_):
    offset = in_.Doc.param("helix_plane_offset")
    helix = in_.Doc.param("helix_angle")
    upper = _spur.tooth_input_plane_at(in_, offset)
    lowerSketch, lowerProfile = _spur.build_tooth_section(in_.World, in_.Lower, in_.Params, 0)
    upperSketch, upperProfile = _spur.build_tooth_section(in_.World, upper, in_.Params, helix.base())
    tooth = _fx.decad_loft(in_.Doc, lowerSketch, lowerProfile, upperSketch, upperProfile, name="Twisted Tooth Loft", body="Tooth")
    return tooth

def _fillet_root_edges(doc, gear, _):
    rootValue = doc.param("root_radius")
    radius = doc.param("helical_fillet_radius")
    if radius.base() <= 0:
        return gear
    root = rootValue.base()
    rootRadiusTolerance = 0.001
    roots = []
    seen = {}
    for face in gear.faces():
        cylinder = face.surface()
        ok = _fx.decad_is_cylinder(cylinder)
        if not ok or (abs(cylinder.Radius.base() - root) > rootRadiusTolerance):
            continue
        for edge in face.edges():
            ok = _fx.decad_is_line3(edge.curve())
            if not ok:
                continue
            start = edge.start().position().Value
            end = edge.end().position().Value
            dx, dy, dz = end.X - start.X, end.Y - start.Y, end.Z - start.Z
            length = math.sqrt(((dx * dx) + (dy * dy)) + (dz * dz))
            if (length == 0) or (abs(abs(dz / length) - 1) >= 0.01):
                continue
            ok = edge in seen
            if ok:
                continue
            seen[edge] = True
            roots = roots + [edge]
    if len(roots) == 0:
        return gear
    selection = None
    for edge in roots:
        start = edge.start().position().Value
        end = edge.end().position().Value
        if selection is None:
            selection = _fx.decad_edges(_fx.decad_endpoint_at(start), _fx.decad_endpoint_at(end))
            continue
        selection.or_(_fx.decad_endpoint_at(start), _fx.decad_endpoint_at(end))
    rounded = _fx.decad_fillet(gear, selection.exactly(len(roots)), radius, name="Root Fillet")
    return rounded

